package com.orbis.app.data;

import androidx.annotation.NonNull;
import androidx.room.Entity;
import androidx.room.Index;
import androidx.room.PrimaryKey;

/**
 * One row per app per day. Written by the usage-tracking layer and read by both
 * the dashboard and the throttle-intensity ranking.
 *
 * <p>The unique index is what makes re-running a refresh idempotent: without it,
 * {@code OnConflictStrategy.REPLACE} has only the autogenerated id to match on
 * and every refresh would append a duplicate row.
 *
 * <p>{@code date} leads it deliberately. SQLite can only use an index whose
 * <i>leading</i> column is constrained, so with {@code app} first the
 * dashboard's {@code WHERE date BETWEEN ?} scanned the whole table - which grows
 * by four rows a day forever. This ordering serves the range query and the
 * uniqueness constraint at once.
 */
@Entity(
        tableName = "usage_log",
        indices = {@Index(value = {"date", "app"}, unique = true)})
public class UsageLog {

    @PrimaryKey(autoGenerate = true)
    public long id;

    /** Package name, e.g. {@code com.instagram.android}. */
    @NonNull
    public String app;

    /** ISO-8601 local date, {@code yyyy-MM-dd}. */
    @NonNull
    public String date;

    public long durationMillis;

    public UsageLog(long id, @NonNull String app, @NonNull String date, long durationMillis) {
        this.id = id;
        this.app = app;
        this.date = date;
        this.durationMillis = durationMillis;
    }
}
